class Solution {
    public int maxReturn(int[] value) {
        int prev2 = 0;   // best total through week i-2
        int prev1 = 0;   // best total through week i-1

        for (int v : value) {
            // either skip this week (keep prev1) or take it (prev2 + v)
            int current = Math.max(prev1, prev2 + v);
            prev2 = prev1;
            prev1 = current;
        }

        return prev1;
    }
}

