def fewest_packs(credits: List[int], target: int) -> int:
    INF = float('inf')
    best = [INF] * (target + 1)
    best[0] = 0                      # zero packs make zero

    for t in range(1, target + 1):
        for c in credits:
            if c <= t and best[t - c] != INF:
                best[t] = min(best[t], best[t - c] + 1)

    return -1 if best[target] == INF else best[target]

