import java.util.*;

class Solution {
    public int fewestPacks(int[] credits, int target) {
        final int UNREACHABLE = Integer.MAX_VALUE;
        int[] best = new int[target + 1];
        Arrays.fill(best, UNREACHABLE);
        best[0] = 0;                     // zero packs make zero

        for (int t = 1; t <= target; t++) {
            for (int c : credits) {
                // c <= t guards the index; the reachability check prevents
                // MAX_VALUE + 1 from overflowing to a negative number.
                if (c <= t && best[t - c] != UNREACHABLE) {
                    best[t] = Math.min(best[t], best[t - c] + 1);
                }
            }
        }

        return best[target] == UNREACHABLE ? -1 : best[target];
    }
}

