def longest_common_subsequence(a: str, b: str) -> int:
    n, m = len(a), len(b)
    # dp[i][j] = LCS length of a[:i] and b[:j]; row/col 0 mean empty prefix
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if a[i - 1] == b[j - 1]:
                # a match is always safe to take - no max needed here
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    return dp[n][m]

