            for (int j = 1; j <= m; ++j) {
                if (a[i - 1] == b[j - 1]) {
                    // a match is always safe to take - no max needed here
                    dp[i][j] = dp[i - 1][j - 1] + 1;
                } else {
                    dp[i][j] = std::max(dp[i - 1][j], dp[i][j - 1]);
                }
            }
        }

        return dp[n][m];
    }
