class Solution {
    public void rotate(int[][] matrix) {
        int n = matrix.length;

        // Pass 1: transpose across the main diagonal.
        // Inner loop starts at c = r + 1 so each pair is swapped exactly once.
        for (int r = 0; r < n; r++) {
            for (int c = r + 1; c < n; c++) {
                int tmp = matrix[r][c];
                matrix[r][c] = matrix[c][r];
                matrix[c][r] = tmp;
            }
        }

        // Pass 2: reverse each row
        for (int r = 0; r < n; r++) {
            int left = 0, right = n - 1;
            while (left < right) {
                int tmp = matrix[r][left];
                matrix[r][left] = matrix[r][right];
                matrix[r][right] = tmp;
                left++;
                right--;
            }
        }
    }
}

