#include <vector>
#include <algorithm>

class Solution {
public:
    void rotate(std::vector<std::vector<int>>& matrix) {
        int n = static_cast<int>(matrix.size());

        // Pass 1: transpose across the main diagonal.
        // Inner loop starts at c = r + 1 so each pair is swapped exactly once.
        for (int r = 0; r < n; ++r) {
            for (int c = r + 1; c < n; ++c) {
                std::swap(matrix[r][c], matrix[c][r]);
            }
        }

        // Pass 2: reverse each row
        for (int r = 0; r < n; ++r) {
            std::reverse(matrix[r].begin(), matrix[r].end());
        }
    }
};

