import java.util.*;

class Solution {
    public List<Object[]> shareOfVoice(String[] answers) {
        Map<String, Double> scores = new HashMap<>();
        double total = 0.0;

        // Step 1: parse and accumulate in a single pass
        for (String answer : answers) {
            for (String token : answer.split(" ")) {
                if (token.isEmpty()) continue;
                int colon = token.lastIndexOf(':');
                String brand = token.substring(0, colon);
                int position = Integer.parseInt(token.substring(colon + 1));
                double points = 1.0 / position;    // first citation is worth the most
                scores.put(brand, scores.getOrDefault(brand, 0.0) + points);
                total += points;
            }
        }

        List<Object[]> ranked = new ArrayList<>();
        if (total == 0.0) return ranked;

        // Step 2: convert to shares, rounded to 4 decimal places
        for (Map.Entry<String, Double> e : scores.entrySet()) {
            double share = Math.round(e.getValue() / total * 10000.0) / 10000.0;
            ranked.add(new Object[]{e.getKey(), share});
        }

        // Step 3: share descending, then name ascending.
        // Compare doubles with an epsilon, never with ==.
        ranked.sort((a, b) -> {
            double sa = (Double) a[1], sb = (Double) b[1];
            if (Math.abs(sa - sb) > 1e-9) return Double.compare(sb, sa);
            return ((String) a[0]).compareTo((String) b[0]);
        });

        return ranked;
    }
}

