#include <string>
#include <vector>
#include <unordered_map>
#include <algorithm>
#include <sstream>
#include <cmath>

class Solution {
public:
    std::vector<std::pair<std::string, double>> shareOfVoice(const std::vector<std::string>& answers) {
        std::unordered_map<std::string, double> scores;
        double total = 0.0;

        // Step 1: parse and accumulate in a single pass
        for (const auto& answer : answers) {
            std::istringstream stream(answer);
            std::string token;
            while (stream >> token) {
                size_t colon = token.rfind(':');
                if (colon == std::string::npos) continue;
                std::string brand = token.substr(0, colon);
                int position = std::stoi(token.substr(colon + 1));
                double points = 1.0 / position;   // first citation is worth the most
                scores[brand] += points;
                total += points;
            }
        }

        std::vector<std::pair<std::string, double>> ranked;
        if (total == 0.0) return ranked;

        // Step 2: convert to shares, rounded to 4 decimal places
        for (const auto& kv : scores) {
            double share = std::round(kv.second / total * 10000.0) / 10000.0;
            ranked.push_back({kv.first, share});
        }

        // Step 3: share descending, then name ascending.
        // Compare doubles with an epsilon, never with ==.
        std::sort(ranked.begin(), ranked.end(),
                  [](const std::pair<std::string, double>& a,
                     const std::pair<std::string, double>& b) {
                      if (std::fabs(a.second - b.second) > 1e-9) return a.second > b.second;
                      return a.first < b.first;
                  });

        return ranked;
    }
};
